package bo.com.ganadero.alertas.infrastructure;import bo.com.ganadero.alertas.application.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Repository;import java.util.UUID;
@Repository public class JdbcAlertaConfiguracion implements AlertaConfiguracionPort{private final JdbcClient jdbc;public JdbcAlertaConfiguracion(JdbcClient j){jdbc=j;}public AlertaConfiguracion obtener(UUID e){return jdbc.sql("select dias_alerta_preparto,dias_alerta_destete from core.configuraciones_empresa where empresa_id=:e").param("e",e).query((r,n)->new AlertaConfiguracion(r.getInt(1),r.getInt(2))).optional().orElse(new AlertaConfiguracion(15,7));}}
